// Package tlsconfig provides the HTTPS certificate of the gateway: a Let's
// Encrypt certificate obtained with a DNS-01 challenge at Cloudflare, or a
// certificate signed by a local CA generated by the gateway.
package tlsconfig

import (
	"context"
	"crypto/tls"
	"errors"
	"path/filepath"

	"github.com/caddyserver/certmagic"
	"github.com/libdns/cloudflare"
	"go.uber.org/zap"
)

// ACMEConfig configures Let's Encrypt.
type ACMEConfig struct {
	Domain             string
	Email              string
	CloudflareAPIToken string
	// Staging uses the Let's Encrypt staging CA (for testing).
	Staging bool
	DataDir string
}

// ACME obtains (and keeps renewing) a certificate for cfg.Domain. The DNS-01
// challenge means the gateway never has to be reachable from the internet.
func ACME(ctx context.Context, cfg ACMEConfig) (*tls.Config, error) {
	if cfg.Domain == "" {
		return nil, errors.New("tls: domain is required")
	}
	if cfg.CloudflareAPIToken == "" {
		return nil, errors.New("tls: CLOUDFLARE_API_TOKEN is required for Let's Encrypt")
	}
	logger, _ := zap.NewProduction()
	var magic *certmagic.Config
	// the cache uses this to find the config when it renews the certificate
	cache := certmagic.NewCache(certmagic.CacheOptions{
		GetConfigForCert: func(certmagic.Certificate) (*certmagic.Config, error) { return magic, nil },
		Logger:           logger,
	})
	magic = certmagic.New(cache, certmagic.Config{
		Storage: &certmagic.FileStorage{Path: filepath.Join(cfg.DataDir, "certmagic")},
		Logger:  logger,
	})

	ca := certmagic.LetsEncryptProductionCA
	if cfg.Staging {
		ca = certmagic.LetsEncryptStagingCA
	}
	issuer := certmagic.NewACMEIssuer(magic, certmagic.ACMEIssuer{
		CA:                      ca,
		Email:                   cfg.Email,
		Agreed:                  true,
		DisableHTTPChallenge:    true,
		DisableTLSALPNChallenge: true,
		DNS01Solver: &certmagic.DNS01Solver{DNSManager: certmagic.DNSManager{
			DNSProvider: &cloudflare.Provider{APIToken: cfg.CloudflareAPIToken},
		}},
		Logger: logger,
	})
	magic.Issuers = []certmagic.Issuer{issuer}

	if err := magic.ManageSync(ctx, []string{cfg.Domain}); err != nil {
		return nil, err
	}
	tlsCfg := magic.TLSConfig()
	tlsCfg.NextProtos = append([]string{"h2", "http/1.1"}, tlsCfg.NextProtos...)
	tlsCfg.MinVersion = tls.VersionTLS12
	return tlsCfg, nil
}
